# t79 — oportunidade por solução: produto TOTVS em destaque + aprofundamento individual (desktop e mobile)
import sys; sys.path.insert(0, '/home/claude/test')
from t40_lib import *
A, errs = open_h('qa.t79@totvs.com.br')
A.evaluate("UI.view='importar'; render()"); A.wait_for_timeout(300)
A.set_input_files('#f-cart', D + 'carteira.xlsx'); A.wait_for_timeout(500); A.click('[data-a=impPrev]'); A.wait_for_timeout(300); A.click('[data-a=impGo]'); A.wait_for_timeout(3000)
A.set_viewport_size({'width': 1440, 'height': 900}); ev(A, "UI.view='oport'; render()"); A.wait_for_timeout(900)
# todo card com solução(ões) exibe o nome de cada solução no destaque
chk = ev(A, """(()=>{let n=0,ok=0,none=0,noneOk=0;document.querySelectorAll('.card.opc .opp').forEach(o=>{const cards=[...o.querySelectorAll('.solstrip .sol-card')];if(!cards.length)return;n++;const t=o.querySelector('table.chain tr td').textContent;const names=cards.filter(c=>!c.classList.contains('sol-none')).map(c=>c.querySelector('.sol-n').textContent.trim());if(names.length){if(names.every(x=>t.includes(x)))ok++}else{none++;if(/Sem solução de produto/.test(cards[0].textContent))noneOk++}});return {n,ok,none,noneOk,total:document.querySelectorAll('.card.opc .opp').length}})()""")
print(chk)
ck('toda oportunidade tem faixa de solução', chk['n'] == chk['total'] and chk['total'] > 0)
ck('nomes no destaque = nomes da tabela (nada inventado)', chk['ok'] + chk['none'] == chk['n'])
ck('sem solução: aviso explícito (retenção)', chk['none'] >= 1 and chk['none'] == chk['noneOk'])
ck('nome do produto em destaque (≥18px)', ev(A, "parseFloat(getComputedStyle(document.querySelector('.sol-card:not(.sol-none) .sol-n')).fontSize)>=18"))
ck('um aprofundamento por solução', ev(A, "[...document.querySelectorAll('.card.opc .opp')].every(o=>{const k=o.querySelectorAll('.sol-card:not(.sol-none)').length;return o.querySelectorAll('details.sol-more').length===k})"))
ck('aprofundamento fechado por padrão', ev(A, "document.querySelectorAll('details.sol-more[open]').length")==0)
A.locator('.sol-card:not(.sol-none) summary').first.click(); A.wait_for_timeout(300)
body = ev(A, "document.querySelector('details.sol-more[open] .sol-body').innerText")
ck('aprofundamento mostra motivo, o que validar e aviso de hipótese', 'POR QUE APARECE' in body.upper() and 'O QUE VALIDAR' in body.upper() and 'não é proposta' in body)
ck('lacuna explícita ou conteúdo documentado (sem inventar)', ('ainda não detalha' in body) or ('FUNCIONALIDADES' in body.upper()) or ('DORES' in body.upper()))
nome = ev(A, "document.querySelector('details.sol-more[open]').closest('.sol-card').querySelector('.sol-n').textContent.trim()")
A.locator('details.sol-more[open] [data-a=solAprof]').click(); A.wait_for_timeout(700)
ck('"Abrir na Base de Soluções" leva ao registro certo', ev(A, "UI.view") == 'solucoes' and ev(A, "!!UI.solSel") and nome.split(' (')[0][:12] in ev(A, "document.querySelector('#app').innerText"))
# Visão: "Onde vale aprofundar hoje" cita o produto
ev(A, "UI.view='geral'; render()"); A.wait_for_timeout(900)
ck('"Onde vale aprofundar hoje" cita o produto TOTVS quando há', ev(A, "(()=>{const h=document.querySelector('#hoje');return !h||!h.querySelector('.hj')||/TOTVS|Configurador|Serviços/.test(h.innerText)||document.querySelectorAll('#hoje .hj b').length>0})()"))
# Raio-X do cliente usa o mesmo card
ev(A, "UI.view='cliente'; UI.sel=1; render()"); A.wait_for_timeout(900)
# mobile: cartão recolhido mantém as soluções visíveis
A.set_viewport_size({'width': 390, 'height': 844}); ev(A, "UI.view='oport'; render()"); A.wait_for_timeout(900)
ck('mobile: soluções visíveis com o card recolhido', ev(A, "(()=>{const o=document.querySelectorAll('.card.opc .opp.mo-c')[1];return !!o&&!o.classList.contains('open')&&getComputedStyle(o.querySelector('.solstrip')).display!=='none'&&getComputedStyle(o.querySelector('table.chain')).display==='none'})()"))
ck('mobile: sem rolagem lateral', ev(A, "document.documentElement.scrollWidth<=innerWidth"))
ck('sem erros de página', not errs)
print('FAILS', F)
p.stop()
